using BusinessPartnerPortal.Api.Common;using BusinessPartnerPortal.Api.Data;using BusinessPartnerPortal.Api.Security;using Microsoft.EntityFrameworkCore;
namespace BusinessPartnerPortal.Api.Features.Documents;
public static class DocumentEndpoints{public static IEndpointRouteBuilder MapDocumentEndpoints(this IEndpointRouteBuilder app){var g=app.MapGroup("/api/v1/documents").RequireAuthorization().WithTags("Documents");
 g.MapGet("/my",async(CurrentUser current,AppDbContext db,CancellationToken ct)=>{var vendorId=await current.GetVendorIdAsync(ct)??throw new ApiException(403,"Vendor mapping missing.");var rows=await(from d in db.Documents join i in db.Invoices on d.InvoiceId equals i.Id where i.VendorId==vendorId&&i.DeletedAt==null orderby d.UploadedAt descending select new{d.Id,d.InvoiceId,i.InvoiceNumber,d.DocumentType,d.OriginalFileName,d.ContentType,d.FileSize,d.UploadedAt}).ToListAsync(ct);return Results.Ok(rows);});
 g.MapGet("/{id:guid}",async(Guid id,CurrentUser current,AppDbContext db,CancellationToken ct)=>{var vendorId=await current.GetVendorIdAsync(ct);var q=from d in db.Documents join i in db.Invoices on d.InvoiceId equals i.Id where d.Id==id&&(current.IsAdmin||i.VendorId==vendorId) select d;var doc=await q.FirstOrDefaultAsync(ct)??throw new ApiException(404,"Document not found.");return Results.File(doc.FileContent,doc.ContentType,doc.OriginalFileName);});return app;}}
